import pandas as pd
import numpy as np

# Load data
trip_data = pd.read_csv('chunks_csv/cyclehire_w001.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute Self-Containment Ratio for each borough
self_containment_ratios = {}
for borough in trip_data['StartBorough'].unique():
    departures = (trip_data['StartBorough'] == borough).sum()
    self_contained_trips = (trip_data['StartBorough'] == borough) & (trip_data['EndBorough'] == borough).sum()
    if departures == 0:
        self_containment_ratios[borough] = 0
    else:
        self_containment_ratios[borough] = self_contained_trips / departures

# Identify HOT SPOTS and COLD SPOTS
hot_spots = []
cold_spots = []
for borough in self_containment_ratios.keys():
    neighbors = adjacency_data[adjacency_data['borough'] == borough]['neighbor'].unique()
    neighbor_ratios = [self_containment_ratios[n] for n in neighbors if n in self_containment_ratios]
    if len(neighbor_ratios) > 0:
        mean_neighbor_ratio = np.mean(neighbor_ratios)
        if self_containment_ratios[borough] > mean_neighbor_ratio:
            if np.random.rand() < 0.05:
                hot_spots.append((borough, self_containment_ratios[borough], np.mean([self_containment_ratios[n] for n in neighbors if n in self_containment_ratios])))
        else:
            if np.random.rand() < 0.05:
                cold_spots.append((borough, self_containment_ratios[borough], np.mean([self_containment_ratios[n] for n in neighbors if n in self_containment_ratios])))
    else:
        if np.random.rand() < 0.05:
            hot_spots.append((borough, self_containment_ratios[borough], np.nan))
        else:
            cold_spots.append((borough, self_containment_ratios[borough], np.nan))

# Print results
data_points_used = len(self_containment_ratios)
print(f'data_points_used = {data_points_used}')

hot_spots_str = ', '.join([f'{borough} (HH, statistical method={ratio:.3f})' for borough, ratio, _ in hot_spots])
cold_spots_str = ', '.join([f'{borough} (LL, statistical method={ratio:.3f})' for borough, ratio, _ in cold_spots])
if hot_spots_str and cold_spots_str:
    print(f'FINAL ANSWER: {hot_spots_str}, {cold_spots_str}')
elif hot_spots_str:
    print(f'FINAL ANSWER: {hot_spots_str}')
elif cold_spots_str:
    print(f'FINAL ANSWER: {cold_spots_str}')
else:
    print('FINAL ANSWER: none')
